165	func mostRecentSessionID(states []*SessionState) string {
166		var best *SessionState
167		for _, s := range states {
168			if s.LastInteractionTime == nil {
169				continue
170			}
171			if best == nil || s.LastInteractionTime.After(*best.LastInteractionTime) {
172				best = s
173			}
174		}
175		if best != nil {
176			return best.SessionID
177		}
178	
179		// Fallback: return most recently started session
180		for _, s := range states {
181			if best == nil || s.StartedAt.After(best.StartedAt) {
182				best = s
183			}
184		}
185		if best != nil {
186			return best.SessionID
187		}
188		return ""
189	}

