async function runCommand(
  sandbox: Pick<E2bSandbox, "commands">,
  command: string,
  opts: CommandOptions = {},
): Promise<string> {
  const result = await sandbox.commands.run(command, opts)
  if ("exitCode" in result && result.exitCode !== 0) {
    throw new Error(
      `Command failed (exit ${result.exitCode}): ${command}\n${result.stderr || result.stdout || ""}`,
    )
  }
  return "stdout" in result ? (result.stdout ?? "") : ""
}

input.new_string:
async function runCommand(
  sandbox: Pick<E2bSandbox, "commands">,
  command: string,
  opts: CommandOptions = {},
): Promise<string> {
  let result
  try {
    result = await sandbox.commands.run(command, opts)
  } catch (error) {
    // The SDK throws CommandExitError on a non-zero exit; it exposes
    // exitCode/stderr getters but stringifies to a bare "exit status N",
    // which is all that survives errorString() downstream. Rewrap into the
    // embedded-message shape (same as daytona) so stored failures stay
    // diagnosable.
    const record =
      typeof error === "object" && error !== null ? (error as Record<string, unknown>) : null
    if (record && typeof record.exitCode === "number") {
      const output =
        typeof record.stderr === "string" && record.stderr.length > 0
          ? record.stderr
          : typeof record.stdout === "string"
            ? record.stdout
            : ""
      throw new Error(`Command failed (exit ${record.exitCode}): ${command}\n${output}`)
    }
    throw error
  }
  if ("exitCode" in result && result.exitCode !== 0) {
    throw new Error(
      `Command failed (exit ${result.exitCode}): ${command}\n${result.stderr || result.stdout || ""}`,
    )
  }
  return "stdout" in result ? (result.stdout ?? "") : ""
}

