// Writes `repo_checkpoint_commits` junction rows. Junction rows may reference
// `repo_checkpoints` rows that haven't landed yet (producer-vs-consumer race);
// the `fk_checkpoint` FK was dropped to make this safe, and consumer JOINs are
// LEFT-joins. Future queries traversing this junction should not assume a
// matching `repo_checkpoints` row is always present.
export async function upsertSyncCommitBatch(
  db: Kysely<DB>,
  repoId: string,
  commits: CommitData[],
): Promise<number> {
  if (commits.length === 0) return 0

  const uniqueCommits = deduplicateCommits(commits)
  const now = new Date(new Date().toISOString())
  let successCount = 0

  for (let i = 0; i < uniqueCommits.length; i += BATCH_SIZE) {
    const batch = uniqueCommits.slice(i, i + BATCH_SIZE)
    const rows = batch.map((c) => ({
      id: generateId(),
      repo_id: repoId,
      checkpoint_id: c.checkpoint_id,
      commit_sha: c.commit_sha,
      synced_at: now,
    }))

    try {
      await db
        .insertInto("repo_checkpoint_commits")
        .values(rows)
        .onDuplicateKeyUpdate({
          synced_at: sql`VALUES(synced_at)`,
        })
        .execute()
      successCount += rows.length
    } catch (e) {
      syncLog("upsert_commit_batch_error", { batch: i / BATCH_SIZE + 1, error: String(e) })
    }
  }

  return successCount
}

