// Deduplicate checkpoints by checkpoint_id (keeps first occurrence)
// MySQL doesn't allow duplicate keys in a single upsert batch
export function deduplicateCheckpoints<T extends { checkpoint_id: string }>(checkpoints: T[]): T[] {
  const seen = new Set<string>()
  return checkpoints.filter((cp) => {
    if (seen.has(cp.checkpoint_id)) return false
    seen.add(cp.checkpoint_id)
    return true
  })
}

