/**
 * Stable server-only identity for the published review session. The HMAC key is
 * never exposed to the source sandbox; only the isolated publisher receives the
 * derived value and canonicalizes the untrusted session metadata to it.
 */
async function reviewProvenanceSessionId(env: Env, run: SandboxRun): Promise<string> {
  if (!env.SESSION_SECRET) throw new Error("Review provenance session binding is not configured")
  if (!run.head_sha) throw new Error("Review provenance session binding requires an immutable HEAD")
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(env.SESSION_SECRET),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  )
  const signature = await crypto.subtle.sign(
    "HMAC",
    key,
    encoder.encode(`review-provenance-v1:${run.id}:${run.head_sha}`),
  )
  const nonce = Array.from(new Uint8Array(signature).slice(0, 16), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("")
  return `review-${nonce}`
}

