/**
 * Server-only HMAC over a run's identity. The key is never exposed to the
 * source sandbox; only the isolated publisher receives values derived from it.
 */
async function reviewProvenanceHmacHex(env: Env, run: SandboxRun, label: string): Promise<string> {
  if (!env.SESSION_SECRET) throw new Error("Review provenance binding is not configured")
  if (!run.head_sha) throw new Error("Review provenance binding requires an immutable HEAD")
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(env.SESSION_SECRET),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  )
  const signature = await crypto.subtle.sign(
    "HMAC",
    key,
    encoder.encode(`${label}:${run.id}:${run.head_sha}`),
  )
  return Array.from(new Uint8Array(signature), (byte) => byte.toString(16).padStart(2, "0")).join(
    "",
  )
}

/**
 * Stable server-only identity for the published review session. Deterministic
 * per (run, reviewed commit) so retries converge; the publisher canonicalizes
 * the untrusted session metadata to it.
 */
async function reviewProvenanceSessionId(env: Env, run: SandboxRun): Promise<string> {
  const hex = await reviewProvenanceHmacHex(env, run, "review-provenance-v1")
  return `review-${hex.slice(0, 32)}`
}

/**
 * Stable server-minted checkpoint ID for the run's review checkpoint. Rendered
 * as 12 lowercase hex characters — the CLI's legacy checkpoint-ID format — so
 * it validates everywhere a checkpoint ID travels. Deterministic per
 * (run, reviewed commit): retries and redeliveries target the same checkpoint,
 * which the publisher resolves idempotently.
 */
async function reviewProvenanceCheckpointId(env: Env, run: SandboxRun): Promise<string> {
  const hex = await reviewProvenanceHmacHex(env, run, "review-checkpoint-v1")
  return hex.slice(0, 12)
}

