// Attaches the completed agent session as a new review checkpoint bound to the
// reviewed commit's SHA (server-minted checkpoint ID, no Entire-Checkpoint
// trailer required), without credentials. This is platform-owned rather than
// dependent on model compliance.
//
// Candidate construction: `entire session attach --checkpoint-id --commit-sha`
// writes the checkpoint onto the sandbox's LOCAL entire/checkpoints/v1 branch,
// whose tip may contain local-only commits (e.g. the reviewer session's own
// eager condense). Bundles list their boundary commits as prerequisites, so a
// candidate parented on a local-only commit could never be fetched by the
// publisher. Instead the script grafts ONLY the new checkpoint directory onto
// the prefetched remote base tree and commits that against the remote base —
// the bundle's sole prerequisite is then a commit the publisher provably has.
export function entireAttachReviewCommand(
  agent: string,
  repoDir: string,
  expectedHeadSha: string,
  expectedCheckpointId: string,
): string {
  assert(repoDir.startsWith("/"), `review attach requires an absolute repo dir: ${repoDir}`)
  assert(
    /^[0-9a-f]{40}$/i.test(expectedHeadSha),
    `review attach requires a full commit SHA: ${expectedHeadSha}`,
  )
  assert(
    /^[A-Za-z0-9_-]{3,128}$/.test(expectedCheckpointId),
    `review attach requires a safe checkpoint id: ${expectedCheckpointId}`,
  )
  const checkpointPath = `${expectedCheckpointId.slice(0, 2)}/${expectedCheckpointId.slice(2)}`

  const sessionInfoPath = "/tmp/entire-review-session.json"
  const indexPath = "/tmp/entire-review-provenance-index"
  // Tolerate non-JSON file contents (older CLIs print a plain-text hint with a
  // zero exit when no session exists): a parse failure yields an empty field,
  // so the explicit no-session guard below fires instead of a node stacktrace.
  const jsonField = (field: string): string =>
    `node -e ${shellQuote(
      `let v;try{v=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8"))}catch{process.exit(0)}const x=v[${JSON.stringify(field)}];if(typeof x==="string")process.stdout.write(x)`,
    )} ${shellQuote(sessionInfoPath)}`

  // Codex never fires the Entire hooks in sandboxes: hook execution requires
  // per-user trust entries in ~/.codex/config.toml ([hooks.state."…"]), which
  // a freshly provisioned sandbox does not have — so no Entire session state
  // is ever written and `entire session current` finds nothing. Recover the
  // session ID straight from codex's on-disk rollout layout
  // (CODEX_HOME/sessions/YYYY/MM/DD/rollout-…-<uuid>.jsonl); `entire session
  // attach --agent codex <uuid>` resolves the transcript from that same
  // layout without needing session state. `|| true` guards keep set -e /
  // pipefail from aborting on the legitimate empty cases (no sessions dir,
  // head closing the pipe).
  const codexSessionFallbackLines =
    entireAgentName(agent) === "codex"
      ? [
          'if [ -z "$session_id" ]; then',
          `  rollout="$(ls -1t "\${CODEX_HOME:-$HOME/.codex}"/sessions/*/*/*/rollout-*.jsonl 2>/dev/null | head -n 1 || true)"`,
          `  session_id="$(basename "\${rollout:-none}" .jsonl | sed -n 's/.*-\\([0-9a-f]\\{8\\}-[0-9a-f]\\{4\\}-[0-9a-f]\\{4\\}-[0-9a-f]\\{4\\}-[0-9a-f]\\{12\\}\\)$/\\1/p' || true)"`,
          "fi",
        ]
      : []

  // Failure messages below are stable contract strings: the queue's
  // reviewProvenanceFailureReason() maps them to low-cardinality reason codes
  // on the review_provenance_failed event. Keep them in sync.
  return bashLoginCommand([
    `cd ${shellQuote(repoDir)}`,
    'actual_head="$(git rev-parse HEAD)"',
    `expected_head=${shellQuote(expectedHeadSha.toLowerCase())}`,
    '[ "${actual_head,,}" = "$expected_head" ] || { echo "review provenance HEAD mismatch: expected $expected_head, got $actual_head" >&2; exit 1; }',
    // The prefetched remote checkpoint tip is the candidate's parent; without
    // it there is no publishable base (repo has never checkpointed).
    'base="$(git rev-parse -q --verify refs/remotes/origin/entire/checkpoints/v1)" || { echo "review provenance requires a fetched checkpoint base" >&2; exit 1; }',
    // A non-zero exit here means "no session state" (newer CLIs); fall
    // through with an empty file so the fallback (codex) or the final
    // no-session guard decides the outcome.
    `entire session current --json > ${shellQuote(sessionInfoPath)} || : > ${shellQuote(sessionInfoPath)}`,
    `session_id="$(${jsonField("session_id")})"`,
    ...codexSessionFallbackLines,
    '[ -n "$session_id" ] || { echo "review provenance could not resolve the current Entire session" >&2; exit 1; }',
    `entire session attach --review --force --agent ${entireAgentName(agent)} --checkpoint-id ${shellQuote(expectedCheckpointId)} --commit-sha "$expected_head" "$session_id" || { echo "review provenance attach failed for session $session_id" >&2; exit 1; }`,
    'final_head="$(git rev-parse HEAD)"',
    '[ "${final_head,,}" = "$expected_head" ] || { echo "review provenance changed HEAD unexpectedly" >&2; exit 1; }',
    'tip="$(git rev-parse refs/heads/entire/checkpoints/v1)"',
    `cp_path=${shellQuote(checkpointPath)}`,
    'git rev-parse -q --verify "$tip:$cp_path" >/dev/null || { echo "review provenance attach produced no checkpoint" >&2; exit 1; }',
    // Graft only the new checkpoint dir onto the remote base tree.
    `export GIT_INDEX_FILE=${shellQuote(indexPath)}`,
    `rm -f ${shellQuote(indexPath)}`,
    'git read-tree "$base^{tree}"',
    'git read-tree --prefix="$cp_path/" "$tip:$cp_path"',
    'new_tree="$(git write-tree)"',
    "unset GIT_INDEX_FILE",
    'candidate_sha="$(GIT_AUTHOR_NAME="Entire Review Runner" GIT_AUTHOR_EMAIL="review-runner@entire.io" GIT_COMMITTER_NAME="Entire Review Runner" GIT_COMMITTER_EMAIL="review-runner@entire.io" git commit-tree "$new_tree" -p "$base" -m "Checkpoint: '${expectedCheckpointId}'")"`,
    `git update-ref ${shellQuote(REVIEW_PROVENANCE_CANDIDATE_REF)} "$candidate_sha"`,
    `rm -f ${shellQuote(REVIEW_PROVENANCE_BUNDLE_PATH)}`,
    `git bundle create ${shellQuote(REVIEW_PROVENANCE_BUNDLE_PATH)} ${shellQuote(REVIEW_PROVENANCE_CANDIDATE_REF)} "^$base"`,
    `git update-ref -d ${shellQuote(REVIEW_PROVENANCE_CANDIDATE_REF)}`,
    `printf "review-provenance-candidate:%s:%s:%s\\n" ${shellQuote(expectedCheckpointId)} "$session_id" "$candidate_sha"`,
  ])
}

