export function entirePublishReviewBundleCommand(
  checkpointRepoUrl: string,
  expectedCheckpointId: string,
  expectedReviewSessionId: string,
  expectedCommitSha: string,
  gitAskpassPath: string,
  bundlePath = REVIEW_PROVENANCE_BUNDLE_PATH,
  maxExpandedBytes = MAX_REVIEW_PROVENANCE_BUNDLE_BYTES,
): string {
  assert(
    /^https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\.git$/.test(checkpointRepoUrl),
    "checkpoint publisher requires a GitHub URL",
  )
  assert(
    /^[A-Za-z0-9_-]{3,128}$/.test(expectedCheckpointId),
    "checkpoint publisher requires a safe checkpoint id",
  )
  assert(
    /^[A-Za-z0-9_-]{3,128}$/.test(expectedReviewSessionId),
    "checkpoint publisher requires a server-issued review session id",
  )
  assert(
    /^[0-9a-f]{40}$/.test(expectedCommitSha),
    "checkpoint publisher requires the reviewed commit SHA",
  )
  assert(
    Number.isSafeInteger(maxExpandedBytes) &&
      maxExpandedBytes > 0 &&
      maxExpandedBytes <= MAX_REVIEW_PROVENANCE_BUNDLE_BYTES,
    "checkpoint publisher requires a bounded expanded size",
  )
  const checkpointPath = `${expectedCheckpointId.slice(0, 2)}/${expectedCheckpointId.slice(2)}`
  // Create-mode contract: the candidate creates ONE new checkpoint directory
  // (the server-minted shard path), containing exactly one agent_review
  // session plus its summary. There is no pre-existing summary to diff
  // against — the whole directory must be additions, and must not exist on
  // the candidate's parent.
  const summaryValidator = String.raw`
const fs = require("fs")
const [newPath, reviewMetadataPath, reviewRoot, checkpointId, expectedCommitSha] = process.argv.slice(1)
const readJson = path => JSON.parse(fs.readFileSync(path, "utf8"))
const newDoc = readJson(newPath)
const review = readJson(reviewMetadataPath)
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b)
const fail = () => process.exit(1)
const tokenKeys = ["input_tokens", "cache_creation_tokens", "cache_read_tokens", "output_tokens", "api_call_count"]
const tokenSchemaKeys = [...tokenKeys, "subagent_tokens"]
const files = value => {
  if (value == null) return []
  if (!Array.isArray(value) || value.some(path => typeof path !== "string")) fail()
  return [...new Set(value)].sort()
}
const usage = (value, rejectExtraKeys = false, depth = 0) => {
  if (value == null) return null
  if (depth > 32 || typeof value !== "object" || Array.isArray(value)) fail()
  if (rejectExtraKeys && Object.keys(value).some(key => !tokenSchemaKeys.includes(key))) fail()
  const normalized = {}
  for (const key of tokenKeys) {
    const amount = value[key] ?? 0
    if (!Number.isSafeInteger(amount) || amount < 0) fail()
    normalized[key] = amount
  }
  const subagentUsage = usage(value.subagent_tokens, rejectExtraKeys, depth + 1)
  if (subagentUsage !== null) normalized.subagent_tokens = subagentUsage
  return normalized
}
if (newDoc.checkpoint_id !== checkpointId) fail()
if (review.checkpoint_id !== checkpointId || review.kind !== "agent_review") fail()
if (typeof review.session_id !== "string" || review.session_id.length === 0 || review.session_id.length > 256) fail()
if (review.strategy !== "manual-commit" || (review.save_step_count ?? 0) !== 0) fail()
if (newDoc.strategy !== "manual-commit") fail()
if (!Number.isSafeInteger(review.checkpoints_count) || review.checkpoints_count < 1) fail()
if (newDoc.checkpoints_count !== review.checkpoints_count) fail()
if (files(review.files_touched).length !== 0) fail()
if (files(newDoc.files_touched).length !== 0) fail()
if (!same(usage(newDoc.token_usage, true), usage(review.token_usage))) fail()
if (newDoc.has_review !== true) fail()
if (newDoc.has_investigation ?? false) fail()
if (newDoc.imported ?? false) fail()
// The commit binding is server-canonicalized later; here just require the
// sandbox declared the same reviewed commit it was launched for.
if (review.commit_sha !== expectedCommitSha || newDoc.commit_sha !== expectedCommitSha) fail()
if (!Array.isArray(newDoc.sessions) || newDoc.sessions.length !== 1) fail()
const added = newDoc.sessions[0]
if (!added || typeof added !== "object" || Array.isArray(added)) fail()
const requiredPathKeys = ["metadata", "transcript", "content_hash", "prompt"]
const optionalPathKeys = ["compact_transcript", "assets_manifest"]
const pathKeys = [...requiredPathKeys, ...optionalPathKeys]
if (Object.keys(added).some(key => !pathKeys.includes(key))) fail()
const validPath = path => typeof path === "string" && /^[A-Za-z0-9._/-]+$/.test(path) && path.replace(/^\/+/, "").startsWith(reviewRoot + "/") && !path.split("/").some(part => part === ".." || part === ".")
for (const key of requiredPathKeys) {
  if (!validPath(added[key])) fail()
}
for (const key of optionalPathKeys) {
  if (added[key] !== undefined && !validPath(added[key])) fail()
}
if (added.metadata.replace(/^\/+/, "") !== reviewRoot + "/metadata.json") fail()
`
  // This script runs only in the fresh publisher. It replaces the source
  // sandbox's attacker-controlled identity fields with the server-issued
  // values: the HMAC session id, and the reviewed commit SHA on both the
