  const canonicalizeReviewMetadata = String.raw`
const fs = require("fs")
const [sessionMetadataPath, summaryPath, expectedSessionId, expectedCommitSha] = process.argv.slice(1)
const metadata = JSON.parse(fs.readFileSync(sessionMetadataPath, "utf8"))
