metadata.commit_sha = expectedCommitSha
fs.writeFileSync(sessionMetadataPath, JSON.stringify(metadata, null, 2) + "\n")
const summary = JSON.parse(fs.readFileSync(summaryPath, "utf8"))
summary.commit_sha = expectedCommitSha
fs.writeFileSync(summaryPath, JSON.stringify(summary, null, 2) + "\n")
`
