    '[ "$changed" -gt 0 ] && [ "$review_metadata" = 1 ] || { echo "candidate must add one agent_review session" >&2; exit 1; }',
    'while IFS=$\'\\t\' read -r status path; do [ "$path" = "$allowed_path/metadata.json" ] && continue; case "$path" in "$review_root"/*) ;; *) echo "candidate added data outside review session" >&2; exit 1 ;; esac; done < <(git diff --name-status "$parent" "$candidate")',
    'git show "$candidate:$allowed_path/metadata.json" > /tmp/entire-candidate-summary.json',
