describe("entireAttachReviewCommand", () => {
  const headSha = "0123456789abcdef0123456789abcdef01234567"
  const checkpointId = "ab12cd34ef56"

  it("attaches the session as a SHA-bound review checkpoint without touching HEAD's message", () => {
    const command = entireAttachReviewCommand("codex", "/home/user/repo", headSha, checkpointId)

    expect(command).toContain("entire session current --json")
    expect(command).toContain(
      `entire session attach --review --force --agent codex --checkpoint-id ${checkpointId}`,
    )
    expect(command).toContain('--commit-sha "$expected_head"')
    expect(command).toContain(headSha)
    // SHA-keyed provenance works on commits without an Entire-Checkpoint
    // trailer — the script must not require or read one.
    expect(command).not.toContain("Entire-Checkpoint")
    // The candidate grafts only the new checkpoint dir onto the prefetched
    // remote base, so the bundle's sole prerequisite is remote history.
    expect(command).toContain("refs/remotes/origin/entire/checkpoints/v1")
    expect(command).toContain("git read-tree --prefix=")
    expect(command).toContain("git commit-tree")
    expect(command).toContain(`Checkpoint: ${checkpointId}`)
    expect(command).toContain("ab/12cd34ef56")
    expect(command).toContain("git bundle create")
    expect(command).toContain(REVIEW_PROVENANCE_BUNDLE_PATH)
  })

  it("maps the platform agent name for review attachment", () => {
    expect(entireAttachReviewCommand("claude", "/home/user/repo", headSha, checkpointId)).toContain(
      "--agent claude-code",
    )
  })

  it("rejects unsafe attachment targets", () => {
    expect(() => entireAttachReviewCommand("codex", "repo", headSha, checkpointId)).toThrow()
    expect(() => entireAttachReviewCommand("codex", "/home/user/repo", "HEAD", checkpointId)).toThrow()
    expect(() => entireAttachReviewCommand("codex", "/home/user/repo", headSha, "not/safe")).toThrow()
  })

  it("guards the session lookup and attach so failures carry stable reason strings", () => {
    const command = entireAttachReviewCommand("codex", "/home/user/repo", headSha, checkpointId)

    // A failing `session current` (non-zero exit) truncates the info file so
    // the fallback or the final no-session guard decides the outcome.
    expect(command).toMatch(/entire session current --json > [^\n]* \|\| : > /)
    expect(command).toContain(
      '[ -n "$session_id" ] || { echo "review provenance could not resolve the current Entire session" >&2; exit 1; }',
    )
    expect(command).toContain("requires a fetched checkpoint base")
    // Non-JSON file contents (older CLI prints a plain-text hint with exit 0)
    // must yield an empty field, not a JSON.parse crash.
    expect(command).toContain("try{v=JSON.parse")
    expect(command).toContain('review provenance attach failed for session $session_id')
  })

  it("falls back to codex's on-disk rollout layout when no session state exists", () => {
    const codexCommand = entireAttachReviewCommand("codex", "/home/user/repo", headSha, checkpointId)
    expect(codexCommand).toContain("rollout-*.jsonl")
    expect(codexCommand).toContain("CODEX_HOME")

    // Claude hooks write session state; no fallback belongs in its script.
    const claudeCommand = entireAttachReviewCommand("claude", "/home/user/repo", headSha, checkpointId)
    expect(claudeCommand).not.toContain("rollout-*.jsonl")
  })
})

