it("classifies the attach and publish scripts' contract strings", () => {
  const cases: Array<[string, string]> = [
    ["review provenance HEAD mismatch: expected a, got b", "head_mismatch"],
    ["review provenance requires a fetched checkpoint base", "no_checkpoint_base"],
    ["review provenance could not resolve the current Entire session", "no_session"],
    ["No active session found in this worktree.", "no_session"],
    [
      "session abc already has checkpoint 795233682e33; rewriting an existing checkpoint as a review is not supported yet",
      "attach_rejected",
    ],
    ["review provenance attach failed for session abc", "attach_rejected"],
    ["review provenance attach produced no checkpoint", "attach_rejected"],
    ["review provenance changed HEAD unexpectedly", "head_moved"],
    ["candidate must add one agent_review session", "publish_rejected"],
    ["candidate checkpoint path already exists on parent", "publish_rejected"],
    ["review checkpoint already exists with different content", "publish_rejected"],
    ["checkpoint publication failed after contention retries", "publish_rejected"],
    ["Review provenance bundle has invalid size: 0", "invalid_bundle"],
    ["command timed out after 120000ms", "timeout"],
    ["some novel failure", "unknown"],
  ]
  for (const [message, expected] of cases) {
    expect(reviewProvenanceFailureReason(new Error(message))).toBe(expected)
  }
})

it("reads structured stderr from e2b-style errors that stringify to 'exit status 1'", () => {
