    stdout: "",
  })
  expect(reviewProvenanceFailureReason(error)).toBe("no_checkpoint_base")
})

describe("entirePublishReviewBundleCommand", () => {
  const commitSha = "cafe".repeat(10)

  it("validates an untrusted candidate in the isolated publisher before pushing", () => {
    const command = entirePublishReviewBundleCommand(
      "https://github.com/owner/checkpoints.git",
      "01ABCDEF1234567890",
      "platform-run-123",
      commitSha,
      "/tmp/askpass.sh",
    )

    expect(command).toContain("/tmp/entire-review-provenance.bundle")
    expect(command).toContain("candidate must have exactly one parent")
    expect(command).toContain("candidate changed path outside checkpoint")
    expect(command).toContain("candidate must only add checkpoint data")
    expect(command).toContain("candidate checkpoint path already exists on parent")
    expect(command).toContain("candidate must add one agent_review session")
    expect(command).toContain("git ls-tree -r -l")
    expect(command).toContain("review session exceeds expanded size limit")
    expect(command).toContain("review checkpoint already exists with different content")
    expect(command).toContain("git push origin HEAD:refs/heads/entire/checkpoints/v1")
    // Subject matches CLI checkpoint commits so v1-branch webhook ingestion
    // hydrates the review checkpoint like any other.
    expect(command).toContain("Checkpoint: 01ABCDEF1234567890")
    expect(command).toContain("Attach review runner provenance")
    expect(command).not.toContain(" rebase ")
    expect(command).toContain("checkpoint publication verification failed")
  })

  it("rejects a malformed reviewed-commit SHA", () => {
    expect(() =>
      entirePublishReviewBundleCommand(
        "https://github.com/owner/checkpoints.git",
        "01ABCDEF1234567890",
        "platform-run-123",
        "HEAD",
        "/tmp/askpass.sh",
      ),
    ).toThrow()
  })

  it("publishes and idempotently replays a valid review-checkpoint bundle", () => {
    const root = mkdtempSync(join(tmpdir(), "entire-review-publisher-"))
    const remote = join(root, "checkpoints.git")
    const work = join(root, "work")
    const winner = join(root, "winner")
    const bundle = join(root, "candidate.bundle")
    const oversizedBundle = join(root, "oversized.bundle")
    const forgedMetadataBundle = join(root, "forged-metadata.bundle")
    const maliciousBundle = join(root, "malicious.bundle")
    const conflictingBundle = join(root, "conflicting.bundle")
    const askpass = join(root, "askpass.sh")
    const gitConfig = join(root, "gitconfig")
    const serverSessionId = "platform-run-123"
    const checkpointId = "ab12cd34ef56"
    const checkpointRelPath = "ab/12cd34ef56"
    const git = (cwd: string, ...args: string[]): string =>
      execFileSync("git", args, { cwd, encoding: "utf8", stdio: "pipe" }).trim()
    const publish = (bundleFile: string, maxBytes?: number): string =>
      entirePublishReviewBundleCommand(
        "https://github.com/owner/checkpoints.git",
        checkpointId,
        serverSessionId,
        commitSha,
        askpass,
        bundleFile,
        maxBytes,
      )
    try {
      mkdirSync(work)
      git(root, "init", "--bare", remote)
      git(work, "init")
      git(work, "config", "user.name", "Test")
      git(work, "config", "user.email", "test@example.com")
      // Parent branch state: an unrelated pre-existing checkpoint — the
      // review checkpoint dir itself must NOT exist yet (create-mode).
      const unrelated = join(work, "cd", "ef0011223344")
      mkdirSync(unrelated, { recursive: true })
      writeFileSync(
        join(unrelated, "metadata.json"),
        JSON.stringify({ checkpoint_id: "cdef0011223344", sessions: [] }),
      )
      git(work, "add", ".")
      git(work, "commit", "-m", "parent")
      git(work, "branch", "-M", "entire/checkpoints/v1")
      git(work, "remote", "add", "origin", remote)
      git(work, "push", "origin", "entire/checkpoints/v1")
      const parent = git(work, "rev-parse", "HEAD")

      const reviewUsage = {
        input_tokens: 10,
        cache_creation_tokens: 20,
        cache_read_tokens: 30,
        output_tokens: 40,
        api_call_count: 2,
        subagent_tokens: {
          input_tokens: 5,
          cache_creation_tokens: 6,
          cache_read_tokens: 7,
          output_tokens: 8,
          api_call_count: 1,
        },
      }
      const checkpoint = join(work, "ab", "12cd34ef56")
      const review = join(checkpoint, "0")
      mkdirSync(review, { recursive: true })
      writeFileSync(
        join(review, "metadata.json"),
        JSON.stringify({
          checkpoint_id: checkpointId,
          session_id: "native-review-session",
          strategy: "manual-commit",
          checkpoints_count: 2,
          files_touched: [],
          token_usage: reviewUsage,
          kind: "agent_review",
          commit_sha: commitSha,
        }),
      )
      writeFileSync(join(review, "full.jsonl"), "{}\n")
      writeFileSync(join(review, "content_hash.txt"), "sha256:review\n")
      writeFileSync(join(review, "prompt.txt"), "review\n")
      const candidateSummary = {
        checkpoint_id: checkpointId,
        strategy: "manual-commit",
        branch: "main",
        checkpoints_count: 2,
        files_touched: [],
        token_usage: reviewUsage,
        sessions: [
          {
            metadata: `/${checkpointRelPath}/0/metadata.json`,
            transcript: `/${checkpointRelPath}/0/full.jsonl`,
            content_hash: `/${checkpointRelPath}/0/content_hash.txt`,
            prompt: `/${checkpointRelPath}/0/prompt.txt`,
          },
        ],
        has_review: true,
        commit_sha: commitSha,
      }
      writeFileSync(join(checkpoint, "metadata.json"), JSON.stringify(candidateSummary))
      git(work, "add", ".")
      git(work, "commit", "-m", `Checkpoint: ${checkpointId}`)
      const candidate = git(work, "rev-parse", "HEAD")
      git(work, "update-ref", "refs/entire/review-candidate", candidate)
      git(work, "bundle", "create", bundle, "refs/entire/review-candidate", `^${parent}`)

      // Oversized: same shape but exceeding the expanded byte cap.
      writeFileSync(join(review, "padding.bin"), "x".repeat(4_096))
      git(work, "add", ".")
      git(work, "commit", "--amend", "--no-edit")
      git(work, "update-ref", "refs/entire/review-candidate", "HEAD")
      git(work, "bundle", "create", oversizedBundle, "refs/entire/review-candidate", `^${parent}`)
      git(work, "reset", "--hard", candidate)

      // Forged summary: inflated counters, fake files_touched, wrong commit binding.
      writeFileSync(
        join(checkpoint, "metadata.json"),
        JSON.stringify({
          ...candidateSummary,
          checkpoints_count: 10_000,
          files_touched: ["forged.ts"],
          token_usage: { ...reviewUsage, output_tokens: 1_000_000 },
          commit_sha: "0".repeat(40),
        }),
      )
      git(work, "add", ".")
      git(work, "commit", "--amend", "--no-edit")
      git(work, "update-ref", "refs/entire/review-candidate", "HEAD")
      git(
        work,
        "bundle",
        "create",
        forgedMetadataBundle,
        "refs/entire/review-candidate",
        `^${parent}`,
      )
      git(work, "reset", "--hard", candidate)

      // Malicious: writes outside the minted checkpoint path.
      writeFileSync(join(work, "outside-checkpoint"), "attacker controlled\n")
      git(work, "add", ".")
      git(work, "commit", "--amend", "--no-edit")
      git(work, "update-ref", "refs/entire/review-candidate", "HEAD")
      git(work, "bundle", "create", maliciousBundle, "refs/entire/review-candidate", `^${parent}`)
      git(work, "reset", "--hard", candidate)

      // Conflicting: same minted checkpoint id, different transcript bytes —
      // must never overwrite an already-published review checkpoint.
      writeFileSync(join(review, "full.jsonl"), '{"different":true}\n')
      writeFileSync(join(review, "content_hash.txt"), "sha256:different\n")
      git(work, "add", ".")
      git(work, "commit", "--amend", "--no-edit")
      git(work, "update-ref", "refs/entire/review-candidate", "HEAD")
      git(work, "bundle", "create", conflictingBundle, "refs/entire/review-candidate", `^${parent}`)
      git(work, "reset", "--hard", candidate)

      // Concurrent writer: an unrelated checkpoint lands on the remote tip
      // after our candidate was bundled — the publisher must retry/replay,
      // not fail or clobber.
      git(root, "clone", "--branch", "entire/checkpoints/v1", remote, winner)
      git(winner, "config", "user.name", "Other Publisher")
      git(winner, "config", "user.email", "other@example.com")
      const winnerCheckpoint = join(winner, "ee", "ff001122aabb")
      mkdirSync(winnerCheckpoint, { recursive: true })
      writeFileSync(
        join(winnerCheckpoint, "metadata.json"),
        JSON.stringify({ checkpoint_id: "eeff001122aabb", sessions: [] }),
      )
      git(winner, "add", ".")
      git(winner, "commit", "-m", "Checkpoint: eeff001122aabb")
      git(winner, "push", "origin", "HEAD:refs/heads/entire/checkpoints/v1")
      const winningTip = git(winner, "rev-parse", "HEAD")

      writeFileSync(askpass, "#!/bin/sh\necho x-access-token\n")
      chmodSync(askpass, 0o700)
      git(
        root,
        "config",
        "--file",
        gitConfig,
        `url.file://${remote}.insteadOf`,
        "https://github.com/owner/checkpoints.git",
      )
      const env = { ...process.env, GIT_CONFIG_GLOBAL: gitConfig }
      expect(() =>
        execFileSync("bash", ["-c", publish(oversizedBundle, 2_048)], { env, stdio: "pipe" }),
      ).toThrow()
      expect(() =>
        execFileSync("bash", ["-c", publish(forgedMetadataBundle)], { env, stdio: "pipe" }),
      ).toThrow()
      expect(() =>
        execFileSync("bash", ["-c", publish(maliciousBundle)], { env, stdio: "pipe" }),
      ).toThrow()
      expect(git(root, `--git-dir=${remote}`, "rev-parse", "entire/checkpoints/v1")).toBe(
        winningTip,
      )

      execFileSync("bash", ["-c", publish(bundle)], { env, stdio: "pipe" })
      const publishedTip = git(root, `--git-dir=${remote}`, "rev-parse", "entire/checkpoints/v1")

      // The transcript blob landed unchanged at the minted path.
      expect(git(work, "rev-parse", `${candidate}:${checkpointRelPath}/0/full.jsonl`)).toBe(
        git(
          root,
          `--git-dir=${remote}`,
          "rev-parse",
          `entire/checkpoints/v1:${checkpointRelPath}/0/full.jsonl`,
        ),
      )
      // Identity fields are server-canonicalized.
      const publishedReviewMetadata = JSON.parse(
        git(
          root,
          `--git-dir=${remote}`,
          "show",
          `refs/heads/entire/checkpoints/v1:${checkpointRelPath}/0/metadata.json`,
        ),
      )
      expect(publishedReviewMetadata.session_id).toBe(serverSessionId)
      expect(publishedReviewMetadata.commit_sha).toBe(commitSha)
      const publishedSummary = JSON.parse(
        git(
          root,
          `--git-dir=${remote}`,
          "show",
          `refs/heads/entire/checkpoints/v1:${checkpointRelPath}/metadata.json`,
        ),
      )
      expect(publishedSummary.checkpoint_id).toBe(checkpointId)
      expect(publishedSummary.commit_sha).toBe(commitSha)
      expect(publishedSummary.has_review).toBe(true)
      expect(publishedSummary.sessions).toHaveLength(1)
      // Commit subject matches CLI checkpoint commits so webhook ingestion
      // hydrates the review checkpoint.
      expect(
        git(root, `--git-dir=${remote}`, "log", "-1", "--format=%s", "entire/checkpoints/v1"),
      ).toBe(`Checkpoint: ${checkpointId}`)

      // Replay is an idempotent no-op: no new commit on the branch.
      execFileSync("bash", ["-c", publish(bundle)], { env, stdio: "pipe" })
      expect(git(root, `--git-dir=${remote}`, "rev-parse", "entire/checkpoints/v1")).toBe(
        publishedTip,
      )

      // Same minted id with different content must be rejected, not overwritten.
      expect(() =>
        execFileSync("bash", ["-c", publish(conflictingBundle)], { env, stdio: "pipe" }),
      ).toThrow(/already exists with different content/)
      expect(git(root, `--git-dir=${remote}`, "rev-parse", "entire/checkpoints/v1")).toBe(
        publishedTip,
      )
    } finally {
      rmSync(root, { recursive: true, force: true })
    }
  }, 20_000)
})

